import{_ as s,c as i,o as t,ae as n}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Get Admin Permissions (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-permissions-gql-all","title":"Full Access Token","query":"query {\\n  getAdminPermissions {\\n    permissionType\\n    permissions\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"getAdminPermissions\\": {\\n      \\"permissionType\\": \\"all\\",\\n      \\"permissions\\": [\\"*\\"]\\n    }\\n  }\\n}\\n"},{"id":"admin-permissions-gql-custom","title":"Custom Access Token","query":"query {\\n  getAdminPermissions {\\n    permissionType\\n    permissions\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"getAdminPermissions\\": {\\n      \\"permissionType\\": \\"custom\\",\\n      \\"permissions\\": [\\"catalog\\", \\"catalog.products\\", \\"sales.orders\\"]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/navigation/permissions.md","filePath":"api/graphql-api/admin/navigation/permissions.md"}'),o={name:"api/graphql-api/admin/navigation/permissions.md"};function a(r,e,d,p,c,l){return t(),i("div",null,e[0]||(e[0]=[n('<h1 id="get-admin-permissions-graphql" tabindex="-1">Get Admin Permissions (GraphQL) <a class="header-anchor" href="#get-admin-permissions-graphql" aria-label="Permalink to &quot;Get Admin Permissions (GraphQL)&quot;">​</a></h1><p>Returns the authenticated token&#39;s effective permissions so you can gate UI up front — show or hide buttons, menus and actions without triggering trial-and-error errors.</p><h2 id="output-fields" tabindex="-1">Output Fields <a class="header-anchor" href="#output-fields" aria-label="Permalink to &quot;Output Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>permissionType</code></td><td>String</td><td>One of <code>all</code>, <code>custom</code>, or <code>same_as_web</code>.</td></tr><tr><td><code>permissions</code></td><td>JSON</td><td>The granted ACL keys, or <code>[&quot;*&quot;]</code> for full access.</td></tr></tbody></table><p><code>permissionType</code> semantics:</p><ul><li><code>all</code> — full access. <code>permissions</code> is <code>[&quot;*&quot;]</code>.</li><li><code>custom</code> — <code>permissions</code> lists the explicitly granted ACL keys.</li><li><code>same_as_web</code> — the token follows the admin&#39;s web role; <code>permissions</code> lists the keys that role currently grants.</li></ul><p>In every case the effective <code>permissions</code> are capped by the admin&#39;s role — a token can never do more than its owner admin can currently do.</p><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',8)]))}const h=s(o,[["render",a]]);export{u as __pageData,h as default};
